import { useEffect, useRef } from 'react';
import { useDispatch } from 'react-redux';

import {
  usePageFilterApplied,
  usePageFilterManagement,
  usePageFilterStatus,
} from 'hooks';
import { mergePageDataFilters } from 'redux/slices/filters';
import { AppDispatch } from 'redux/types';

import { PERFORMANCE_AND_BREAKDOWN_FILTER_CATALOG_PATCH } from '../__mocks__/filterCatalog';
import { INNOVATION_HUB_PAGE_NAME } from '../../../constants';
import { PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY } from '../constants';

const CASCADE_RESETS: Record<string, string[]> = {
  country: ['brands', 'sub_brands', 'sku'],
  brands: ['sub_brands', 'sku'],
  sub_brands: ['sku'],
};

export function usePerformanceAndBreakdownLocalFilters(): void {
  const dispatch = useDispatch<AppDispatch>();
  const { isLoaded } = usePageFilterStatus(INNOVATION_HUB_PAGE_NAME);
  const { applied } = usePageFilterApplied(INNOVATION_HUB_PAGE_NAME);
  const { updateForm, apply } = usePageFilterManagement(
    INNOVATION_HUB_PAGE_NAME,
  );

  const hasMergedLocalFiltersRef = useRef(false);
  const prevAppliedRef = useRef(applied);

  useEffect(() => {
    if (
      !PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY ||
      !isLoaded ||
      hasMergedLocalFiltersRef.current
    ) {
      return;
    }

    hasMergedLocalFiltersRef.current = true;
    dispatch(
      mergePageDataFilters({
        pageName: INNOVATION_HUB_PAGE_NAME,
        patch: PERFORMANCE_AND_BREAKDOWN_FILTER_CATALOG_PATCH,
      }),
    );
  }, [dispatch, isLoaded]);

  useEffect(() => {
    const prevApplied = prevAppliedRef.current;
    prevAppliedRef.current = applied;

    for (const [sourceKey, resetKeys] of Object.entries(CASCADE_RESETS)) {
      if (prevApplied[sourceKey] === applied[sourceKey]) {
        continue;
      }

      for (const key of resetKeys) {
        updateForm(key, null);
      }
      apply();
      break;
    }
  }, [applied, updateForm, apply]);
}
